#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *dup_word(const char *w)
{
    size_t len = strlen(w);
    char *p = malloc(len + 1);
    if (!p) return NULL;
    memcpy(p, w, len + 1);
    return p;
}

int main(void)
{
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;

    char **words = malloc((size_t)n * sizeof *words);
    if (!words) return 1;

    char buf[64];
    for (int i = 0; i < n; i++) {
        if (scanf("%63s", buf) != 1) { n = i; break; }
        words[i] = dup_word(buf);
    }

    for (int i = n - 1; i >= 0; i--)
        printf("%s\n", words[i]);

    for (int i = 0; i < n; i++)   /* FIX: release every word ... */
        free(words[i]);
    free(words);                  /* ... then the array that held them */
    return 0;
}
